using System;
using System.IO;
using System.Linq;
using System.Threading;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Threading;
using Forms=System.Windows.Forms;

namespace Kora {
 public class Widget : Window {
  Store store;State state;StackPanel rows;TextBlock progress,date,status;Grid track;Border fill;DesktopHost host;DispatcherTimer timer;DateTime stamp,day=DateTime.Today;EventWaitHandle wake;Forms.NotifyIcon tray;bool preview;
  public Widget(Store storage,bool isPreview){store=storage;preview=isPreview;state=store.Read();Title="Kora Desk · 桌面组件";Width=356;Height=620;ResizeMode=ResizeMode.NoResize;ShowInTaskbar=false;WindowStartupLocation=WindowStartupLocation.Manual;Left=100;Top=90;
   var body=new Grid{Margin=new Thickness(23,22,23,18)};body.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});body.RowDefinitions.Add(new RowDefinition());body.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});
   var header=new StackPanel();var top=new DockPanel();var menu=Ui.Button("···",OpenMenu);menu.FontSize=21;menu.Padding=new Thickness(8,0,0,4);menu.ToolTip="组件选项";DockPanel.SetDock(menu,Dock.Right);top.Children.Add(menu);var grip=new StackPanel{Background=Brushes.Transparent,Cursor=System.Windows.Input.Cursors.SizeAll};var brand=Ui.Text("kora  /  刻序",12,Ui.Accent);brand.FontWeight=FontWeights.SemiBold;grip.Children.Add(brand);var title=Ui.Text("今天的事",26);title.FontWeight=FontWeights.SemiBold;title.Margin=new Thickness(0,12,0,7);grip.Children.Add(title);date=Ui.Text("",12,Ui.Muted);grip.Children.Add(date);top.Children.Add(grip);header.Children.Add(top);
   var stats=new DockPanel{Margin=new Thickness(0,23,0,11)};progress=Ui.Text("",12,Ui.Accent);stats.Children.Add(progress);header.Children.Add(stats);track=new Grid{Height=3,Background=Ui.Line,Margin=new Thickness(0,0,0,13)};fill=new Border{Background=Ui.Accent,CornerRadius=new CornerRadius(2),HorizontalAlignment=HorizontalAlignment.Left};track.Children.Add(fill);header.Children.Add(track);body.Children.Add(header);
   rows=new StackPanel();var scroll=new ScrollViewer{Content=rows,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};Grid.SetRow(scroll,1);body.Children.Add(scroll);
   var footer=new DockPanel{Margin=new Thickness(0,14,0,0)};var open=Ui.Button("打开计划  ↗",()=>Launch.App("Kora.exe"));open.FontSize=11;open.Padding=new Thickness(0,4,0,4);DockPanel.SetDock(open,Dock.Right);footer.Children.Add(open);status=Ui.Text("桌面组件",10,Ui.Muted);status.VerticalAlignment=VerticalAlignment.Center;footer.Children.Add(status);Grid.SetRow(footer,2);body.Children.Add(footer);Ui.WindowFrame(this,body,24);
   if(!preview)host=new DesktopHost(this,store,grip);else Ui.Drag(this,grip);
   wake=new EventWaitHandle(false,EventResetMode.AutoReset,"Local\\KoraDesk.Widget.Wake");timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};timer.Tick+=Tick;Loaded+=delegate{Refresh();timer.Start();};Closed+=delegate{timer.Stop();wake.Dispose();if(tray!=null){tray.Visible=false;tray.Dispose();}};SizeChanged+=delegate{UpdateProgress();};if(!preview)MakeTray();Refresh();
  }
  void MakeTray(){tray=new Forms.NotifyIcon{Text="Kora Desk · 刻序",Visible=true};var icon=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Kora.ico");tray.Icon=File.Exists(icon)?new System.Drawing.Icon(icon):System.Drawing.SystemIcons.Application;var menu=new Forms.ContextMenuStrip();menu.Items.Add("打开计划",null,delegate{Ui.Guard(()=>Launch.App("Kora.exe"));});menu.Items.Add("显示 / 隐藏组件",null,delegate{if(IsVisible)Hide();else{Show();host.Apply(store.Read().Settings);}});menu.Items.Add("切换桌面 / 置顶",null,delegate{Ui.Guard(()=>{store.Update(s=>s.Settings.AlwaysOnTop=!s.Settings.AlwaysOnTop);Refresh();});});menu.Items.Add(new Forms.ToolStripSeparator());menu.Items.Add("退出组件",null,delegate{Close();});tray.ContextMenuStrip=menu;tray.DoubleClick+=delegate{Ui.Guard(()=>Launch.App("Kora.exe"));};}
  void OpenMenu(){var menu=new ContextMenu{PlacementTarget=this};var toggle=new MenuItem{Header=state.Settings.AlwaysOnTop?"✓ 始终置顶（点击关闭）":"切换为始终置顶"};toggle.Click+=delegate{Ui.Guard(()=>{store.Update(s=>s.Settings.AlwaysOnTop=!s.Settings.AlwaysOnTop);Refresh();});};menu.Items.Add(toggle);var open=new MenuItem{Header="编辑每周计划"};open.Click+=delegate{Ui.Guard(()=>Launch.App("Kora.exe"));};menu.Items.Add(open);var hide=new MenuItem{Header="隐藏组件（可从托盘恢复）"};hide.Click+=delegate{Hide();};menu.Items.Add(hide);menu.IsOpen=true;}
  void Tick(object sender,EventArgs e){if(wake.WaitOne(0)){Show();if(host!=null)host.Apply(store.Read().Settings);}var current=File.GetLastWriteTimeUtc(store.FilePath);if(current!=stamp||day!=DateTime.Today)Ui.Guard(Refresh);if(host!=null)status.Text=host.Status;}
  void Refresh(){var old=state.Settings;state=store.Read();stamp=File.GetLastWriteTimeUtc(store.FilePath);day=DateTime.Today;date.Text=day.ToString("M 月 d 日")+"  ·  "+Dates.Short[(int)day.DayOfWeek];rows.Children.Clear();var tasks=state.ForDay(day);Height=Math.Min(SystemParameters.WorkArea.Height-24,350+Math.Min(tasks.Count,8)*45);foreach(var g in tasks.GroupBy(t=>t.Group)){var label=Ui.Text(g.Key,10,Ui.Muted);label.Margin=new Thickness(2,13,0,5);rows.Children.Add(label);foreach(var t in g){var task=t;rows.Children.Add(Ui.TaskRow(task,state.IsDone(task,day),value=>{store.Update(s=>s.SetDone(task.Id,day,value));Refresh();},null,true));}}if(tasks.Count==0){var empty=Ui.Text("今天留白，\n也很好。",20,Ui.Muted);empty.Margin=new Thickness(0,40,0,0);rows.Children.Add(empty);}UpdateProgress();if(host!=null&&(old.AlwaysOnTop!=state.Settings.AlwaysOnTop||old.X!=state.Settings.X||old.Y!=state.Settings.Y))host.Apply(state.Settings);}
  void UpdateProgress(){if(state==null||track==null)return;var tasks=state.ForDay(day);int n=tasks.Count(t=>state.IsDone(t,day));progress.Text=n==tasks.Count&&n>0?"全部完成  ·  今天辛苦了":"已完成 "+n+" / "+tasks.Count;fill.Width=tasks.Count==0?0:Math.Max(0,track.ActualWidth)*n/tasks.Count;}
 }
 public static class WidgetProgram {
  [STAThread] public static int Main(string[] args){bool preview=args.Contains("--preview");Mutex mutex=null;try{bool first;mutex=new Mutex(true,"Local\\KoraDesk.Widget",out first);if(!first&&!preview){using(var e=EventWaitHandle.OpenExisting("Local\\KoraDesk.Widget.Wake"))e.Set();return 0;}var app=new Application{ShutdownMode=ShutdownMode.OnMainWindowClose};Ui.Init(app);var win=new Widget(new Store(),preview);if(preview)win.Loaded+=delegate{win.Dispatcher.BeginInvoke(new Action(()=>{Ui.Snapshot(win,Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"widget.png"));win.Close();}),DispatcherPriority.ApplicationIdle);};app.Run(win);return 0;}catch(Exception e){if(preview){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"preview-error.txt"),e.ToString());return 1;}MessageBox.Show(e.Message,"Kora Desk · 组件无法启动",MessageBoxButton.OK,MessageBoxImage.Warning);return 1;}finally{if(mutex!=null)mutex.Dispose();}}
 }
}
